  function metricTone(label,value){const text=String(value).toLowerCase(),n=Number((text.match(/-?\d+(?:\.\d+)?/)||[])[0]);if(text.includes('unknown')||text.includes('offline')||text==='—')return'is-unknown';if(/lpg|calibrated/.test(label.toLowerCase()))return n>=300?'is-danger':n>=180?'is-attention':'is-safe';if(/อัตรา|rate|drift/.test(label.toLowerCase()))return n>=6?'is-danger':n>=2?'is-attention':'is-safe';if(/confidence|health|battery/.test(label.toLowerCase()))return n<60?'is-danger':n<80?'is-attention':'is-safe';if(/signal/.test(label.toLowerCase()))return n<=-80?'is-danger':n<=-65?'is-attention':'is-safe';if(/humidity/.test(label.toLowerCase()))return n>=80?'is-danger':n>=70?'is-attention':'is-safe';if(/temperature/.test(label.toLowerCase()))return n<18||n>40?'is-danger':n<22||n>36?'is-attention':'is-safe';if(/risk|anomaly/.test(label.toLowerCase()))return n>=72?'is-danger':n>=38?'is-attention':'is-safe';return'';}
  function metric(label, value, detail, icon, tone) { return `<article class="metric ${tone||metricTone(label,value)}"><div class="metric-label"><span class="metric-icon" aria-hidden="true">${icon}</span>${label}</div><div class="metric-value">${value}</div><div class="metric-detail">${detail}</div></article>`; }
