    const list=$('service-request-list');if(list)list.innerHTML=service.state.requests.map(requestCard).join('')||'<p>ยังไม่มีคำขอรับบริการ</p>';
    const taskList=$('service-maintenance-actions');if(taskList)taskList.innerHTML=service.state.tasks.map(t=>`<div class="maintenance-item"><strong>${escape(t.actionType)} · ${escape(t.maintenanceTaskId)}</strong><p>${escape(t.description||'งานตรวจจำลอง')} · ${escape(t.status)} · Incident ${escape(t.incidentId||'—')}</p></div>`).join('')||'<p>ยังไม่มีงานช่างจากคำขอบริการ</p>';
    const queue=$('service-work-queue');if(queue)queue.innerHTML=service.state.requests.map(r=>{const v=service.state.verifications.find(x=>x.requestId===r.requestId),actions=[];if(r.status==='submitted')actions.push(['acknowledged','รับทราบ']);if(r.status==='acknowledged')actions.push(['scheduled','จัดตาราง'],['in_progress','เริ่มงาน']);if(r.status==='scheduled')actions.push(['in_progress','เริ่มงาน']);if(r.status==='in_progress'){actions.push(['task','สร้างงานตรวจ'],['awaiting_verification','ส่งตรวจยืนยัน'],['unable_to_complete','ทำต่อไม่ได้']);}if(r.status==='awaiting_verification'){actions.push(['verify_passed','ยืนยันผ่าน'],['verify_failed','ยืนยันไม่ผ่าน']);if(v?.result==='passed')actions.push(['completed','ปิดงาน']);}if(r.status==='unable_to_complete')actions.push(['in_progress','กลับไปทำต่อ']);actions.push(['report','สร้างรายงาน']);return `${requestCard(r)}<div class="incident-actions">${actions.map(a=>`<button class="button button-secondary" data-service-action="${a[0]}" data-request-id="${escape(r.requestId)}" type="button">${a[1]}</button>`).join('')}</div>`;}).join('')||'<p>ยังไม่มีคิวงานบริการ</p>';
    const reports=$('service-report-list');if(reports)reports.innerHTML=service.state.reports.map(r=>`<article class="incident-card"><header><div><h3>${escape(r.reportId)} · ${escape(r.technicianWorkflowResult)}</h3><p>${escape(r.reportedIssue||'ไม่มีรายละเอียด')} · ${r.mock?'Mock report':''}</p></div><span class="status-pill ${r.detectionStatusAtCompletion==='resolved'?'safe':'attention'}">Detection: ${escape(r.detectionStatusAtCompletion||'ไม่มี Incident')}</span></header><p>${r.detectionStatusAtCompletion&&r.detectionStatusAtCompletion!=='resolved'?'Incident ยังอยู่ในสถานะตรวจจับที่เปิดอยู่ จึงต้องติดตามแยกจากรายงานช่าง':''}</p></article>`).join('')||'<p>ยังไม่มีรายงานการบริการ</p>';
    const form=$('service-request-form');if(form&&!form.dataset.bound){form.dataset.bound='true';form.addEventListener('submit',e=>{e.preventDefault();const current=engine.state.events.find(x=>x.lifecycleStatus!=='resolved'&&(x.eventType==='gas_risk'||x.eventType==='system_fault'));const result=service.create({incidentId:current?incidentId(current):null,requestType:$('service-request-type').value,description:$('service-description').value,contactPreference:$('service-contact').value,title:current?'ขอให้ช่างตรวจสอบ Incident':'ขอให้ช่างตรวจสอบระบบ'});toast(result.duplicate?'มีคำขอที่เปิดอยู่แล้ว':'ส่งคำขอจำลองแล้ว',result.duplicate?result.request.requestId:'ข้อมูลถูกเก็บใน local browser');render();});}
    document.querySelectorAll('[data-service-action]').forEach(button=>button.addEventListener('click',()=>{const requestId=button.dataset.requestId,action=button.dataset.serviceAction;let ok=true;if(action==='task')ok=Boolean(service.task(requestId,{description:'ตรวจอุปกรณ์และ telemetry ในโหมดจำลอง'}));else if(action==='verify_passed')ok=Boolean(service.verify(requestId,{result:'passed',observedResult:'Mock verification passed'}));else if(action==='verify_failed')ok=Boolean(service.verify(requestId,{result:'failed',observedResult:'Mock verification failed'}));else if(action==='report')ok=Boolean(service.report(requestId));else ok=service.transition(requestId,action,'technician');toast(ok?'อัปเดต workflow ช่างแล้ว':'ยังเปลี่ยนสถานะนี้ไม่ได้','ข้อมูลทดสอบใน local browser; Detection lifecycle ไม่ถูกเปลี่ยน');render();}));
    const evidence=$('incident-evidence-json');if(evidence){const selected=engine.state.events.find(event=>incidentId(event)===selectedIncidentId)||engine.state.events[0]||null;const related=selected?service.state.requests.filter(request=>request.incidentId===incidentId(selected)):[];evidence.textContent=JSON.stringify({label:'UNVALIDATED_PROTOTYPE',selectedIncident:selected,currentUnknown:engine.analysis.safety==='unknown',serviceWorkflow:{requests:related,tasks:service.state.tasks.filter(task=>selected&&task.incidentId===incidentId(selected)),verifications:service.state.verifications.filter(item=>selected&&item.incidentId===incidentId(selected)),reports:service.state.reports.filter(report=>selected&&report.incidentId===incidentId(selected)),storageWarning:service.state.warning||engine.state.retentionWarning||null},note:'All service evidence is local mock data; it is not a certified safety or service record.'},null,2);}
