  function renderSpatial(f){const plan=ensureFloorPlan(),coords=(key,fallback)=>Number.isInteger(plan[key])?[plan[key]%12,Math.floor(plan[key]/12)]:fallback,selected=$('layout-select').value,p=selected==='custom'?{title:'แปลนจากการติดตั้ง',copy:'ตำแหน่งในหน้านี้มาจากแปลน 2D ที่บันทึกไว้ใน Provisioning workspace',source:coords('source',[2,6]),sensor:coords('sensor',[9,5]),vent:coords('vent',[10,1]),door:coords('door',[5,0]),context:`${setupProfile.name||'Unregistered site'} · custom plan`}:layoutPresets[selected],strength=f.safety==='critical'?4:f.safety==='attention'?3:f.safety==='unknown'?0:1,map=$('spatial-map');map.innerHTML=Array.from({length:96},(_,i)=>{const x=i%12,y=Math.floor(i/12),level=strength?Math.max(0,Math.min(4,Math.round(strength-Math.hypot(x-p.source[0],y-p.source[1])*.72))):0;return `<span class="gas-cell ${level?`level-${level}`:''}" aria-hidden="true"></span>`}).join('')+`<div class="spatial-fixture fixture-source" style="left:${(p.source[0]+.3)/12*100}%;bottom:${(7-p.source[1])/8*100}%">แหล่งกำเนิด</div><div class="spatial-fixture fixture-sensor" style="left:${(p.sensor[0]+.1)/12*100}%;bottom:${(7-p.sensor[1])/8*100}%">Sensor</div><div class="spatial-fixture fixture-vent" style="left:${(p.vent[0]+.1)/12*100}%;top:${(p.vent[1]+.3)/8*100}%">ระบายอากาศ</div><div class="spatial-fixture fixture-door" style="left:${(p.door[0]+.1)/12*100}%;top:${(p.door[1]+.3)/8*100}%">ประตู</div>`;$('spatial-title').textContent=p.title;$('spatial-copy').textContent=p.copy;$('spatial-state').textContent=f.safety==='unknown'?'ไม่แสดงการกระจายเมื่อข้อมูลไม่พร้อม':`${statusText(f.safety)} · Synthetic dispersion`; $('spatial-facts').innerHTML=[['พื้นที่',p.context],['LPG ล่าสุด',`${f.current.gas.value} ppm`],['Risk state',statusText(f.safety)],['Source context',f.current.system.valve==='closed'?'valve closed':'valve open']].map(x=>`<div><dt>${x[0]}</dt><dd>${x[1]}</dd></div>`).join('');}
