    $('plan-status').textContent=`${plan.entities.length} จุด · ${counts.find(x=>x[0]==='sensor')[1].length} sensor`;
    $('plan-facts').innerHTML=counts.map(([type,items])=>`<div><dt>${planTypes[type].label}</dt><dd>${items.length?items.map(x=>`${pointName(x.cell)}${x.placement==='recommended'?' · แนะนำ':''}`).join('<br>'):'ยังไม่วาง'}</dd></div>`).join('');
